  const feedCard = (title,copy,tags='') => `<article class="feed-card"><div class="feed-top"><span class="feed-avatar">🐌</span><span><b>Schnecke Schneck</b><small>Öffentlicher Social-Media-Beitrag</small></span></div><h4>${title}</h4><p>${copy}</p>${tags?`<small class="feed-tags">${tags}</small>`:''}</article>`;

