  function renderHome(){
    const featured = HOME_APP_IDS;
    return `${appHero('WILLKOMMEN IN DER DIGITALEN WELT','Schnecke Schneck.','Schön, dass du hier bist! Entdecke Projekte, Technik, Social Media und die kleine Schneckenwelt – alles übersichtlich in einer interaktiven Smartphone-Oberfläche.','🐌')}
      <div class="visitor-welcome"><b>Eine Schnecke. Viele Ideen. Eine digitale Welt.</b><p>Stöbere durch die Apps, entdecke aktuelle Inhalte und finde die passenden Kontakt- und Projektbereiche.</p></div>
      ${section('Entdecke die Bereiche')}<div class="website-pages">${featured.map(id=>{const a=APPS.find(x=>x.id===id);return `<button type="button" data-app="${id}"><span>${a.icon}</span><b>${localizedAppName(a.id)}</b><small>${localizedAppHint(a)}</small></button>`;}).join('')}</div>
      ${section('Im Spotlight')}<div class="project-list">${projectOpen('projects','🧩','Projektwelt','Alle Projekte und Technikbereiche an einem Ort')}${projectOpen('images','🖼️','Bildergalerie','Öffentliche Bilder der Fan-Webseite entdecken')}${projectOpen('social','📸','Social-Media-Feed','Öffentliche Beiträge entdecken')}</div>
      ${section('Kontakt')}<div class="project-list">${internalAppButton('contact','Alle Kontaktwege und Möglichkeiten ansehen')}</div>${WIX_FOOTER}`;
  }

  function renderAbout(){return `${appHero('ÜBER DEN CREATOR','Schnecke Schneck.','Ein Creator aus Bottrop mit Begeisterung für Technik, Programmierung, digitale Ideen und Schnecken.','🐌')}
    <p class="body-copy"><b>Mein Name ist Schnecke Schneck!</b></p>
    <p class="body-copy">Willkommen auf meiner Fan-Webseite!</p>
    <p class="body-copy">Ich bin 19 Jahre alt und komme aus Bottrop. Meine größte Leidenschaft ist das Programmieren sowie die Entwicklung von Webseiten und eigenen digitalen Projekten. Ich liebe es, neue Ideen auszuprobieren und diese in funktionierende Anwendungen umzusetzen. Dabei nutze ich auch moderne Technologien wie künstliche Intelligenz, zum Beispiel ChatGPT, um meine Projekte weiterzuentwickeln und zu verbessern 💻🤖</p>
    <p class="body-copy">In meiner Freizeit arbeite ich an verschiedenen eigenen Projekten, darunter Apps, Webseiten und eigene Systeme wie mein IPTV-Setup oder sogar eine eigene KI. Außerdem beschäftige ich mich mit App-Modifikationen und teste neue Funktionen, um immer mehr dazuzulernen. Ich entwickle mich ständig weiter und arbeite kontinuierlich daran, meine Fähigkeiten zu verbessern – Stillstand gibt es bei mir nicht 🚀</p>
    <p class="body-copy">Neben meinen Projekten bin ich auch als Content Creator aktiv und teile regelmäßig Einblicke in meine Arbeit und mein Leben auf Social Media. Du findest mich auf Instagram und TikTok unter @schnecke_schneck2007 📱</p>
    <p class="body-copy">Zusätzlich habe ich ein eigenes Google-Unternehmensprofil für mein Projekt „Schnecke-Schneck Creator Studio“, über das ich Updates, Beiträge und Informationen veröffentliche. So können mich Leute auch über Google und Maps finden und meine Projekte entdecken 🔍</p>
    <p class="body-copy">Ich freue mich immer über Nachrichten, Feedback oder einfach nette Gespräche 😊 Du kannst mich jederzeit über Social Media oder direkt hier über die Webseite kontaktieren.</p>
    <p class="body-copy">Vielen Dank für deine Unterstützung und viel Spaß beim Erkunden meiner Seite!<br><br>Euer Schnecke 🐌✨</p>
    ${section('Auf einen Blick')}<div class="info-grid">${infoCard('📍','Bottrop','Deutschland')}${infoCard('🎂','19 Jahre','Angabe aus der öffentlichen Profilseite')}${infoCard('💻','IT & Web','Webseiten, Apps und Systeme')}${infoCard('🤖','KI & ChatGPT','Ideen, Lernen und Entwicklung')}${infoCard('🎥','Content Creation','Instagram und TikTok')}${infoCard('🐌','Schneckenwelt','Eine kleine Schnecke gehört ebenfalls dazu.')}</div>
    ${section('Themen')}<div class="pill-row">${['Webentwicklung','Android','Künstliche Intelligenz','Datenschutz','Digitale Systeme','Social Media','Schnecken 🐌'].map(pill).join('')}</div>
    ${external(URLS.about,'Originale Profilseite ansehen',true)}`;}

